    /** Remind an OPEN or PENDING claim, once per sheet's today. */
    @PostMapping("/claims/{claimId}/remind")
    public PersonView remind(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user) {
        String sheet = sheetId.trim();
        return view(sheet, claims.remind(sheet, user.trim(), claimId));
    }

    /** Add a proof to a claim, raising its proofs count by one. */
    @PostMapping("/claims/{claimId}/proof")
    public PersonView addProof(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId, @RequestHeader("X-User") @NotBlank String user) {
        String sheet = sheetId.trim();
        return view(sheet, claims.addProof(sheet, user.trim(), claimId));
    }

    /** Add a line to a DRAFT claim, as the signed-in user. */
    @PostMapping("/claims/{claimId}/lines")
    public PersonView addLine(@PathVariable @NotBlank @Size(max = 100) String sheetId,
        claims.flush();
        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
        events.publishEvent(new ClaimLineAdded(sheetId, user, person, claim.getAmount(), claim.getDate(),
                claim.getShownNumber(), label.strip(), qty, at));
        rollup.changed(sheetId, user, before);
        return claim.getPersonId();
    }

    /**
     * Add a proof to a claim, raising its proofs count by one. A SETTLED or VOID claim, or a claim dated
     * inside a closed period, is refused and nothing changes. Returns the person it belongs to.
     */
    @Transactional
    public long addProof(String sheetId, String user, long claimId) {
        Claim claim = claim(sheetId, claimId);
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot take a proof");
        }
        claim.addProof();
        claims.flush();
        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
        events.publishEvent(new ClaimProofAdded(sheetId, user, person, claim.getAmount(), claim.getDate(),
                claim.getShownNumber(), claim.getProofs()));
        return claim.getPersonId();
    }

